//! The family look shared with Convert64: egui visuals for both themes, spacing, text styles and fonts.
//!
//! Copied, unchanged apart from this header and font paths, from Convert64's generated theme
//! (`crates/convert64-app/src/theme/generated.rs` at commit 6c2d90b, 2026-10-13). That file is generated by Convert64's
//! `cargo xtask tokens` from the family's Figma variables. Do not edit it here: change the shared tokens, then copy again.
//! Generating it from one shared source in both repositories is planned for E10 (`design/README.md`).

use egui::{Color32, CornerRadius, FontFamily, FontId, Margin, TextStyle};
use std::collections::BTreeMap;

/// An opaque colour from `0xrrggbb`.
const fn rgb(hex: u32) -> Color32 {
    let [_, r, g, b] = hex.to_be_bytes();
    Color32::from_rgb(r, g, b)
}

/// A colour from `0xrrggbbaa` with unmultiplied alpha, as Figma stores it.
const fn rgba(hex: u32) -> Color32 {
    let [r, g, b, a] = hex.to_be_bytes();
    Color32::from_rgba_unmultiplied_const(r, g, b, a)
}

/// `egui / Visuals`, Light mode, applied over `egui::Visuals::light()`.
pub fn apply_light(v: &mut egui::Visuals) {
    v.widgets.noninteractive.weak_bg_fill = rgb(0xf8f8f8);
    v.widgets.noninteractive.bg_fill = rgb(0xf8f8f8);
    v.widgets.noninteractive.bg_stroke.color = rgb(0xbebebe);
    v.widgets.noninteractive.fg_stroke.color = rgb(0x505050);
    v.widgets.inactive.weak_bg_fill = rgb(0xe6e6e6);
    v.widgets.inactive.bg_fill = rgb(0xe6e6e6);
    v.widgets.inactive.bg_stroke.color = rgba(0x00000000);
    v.widgets.inactive.fg_stroke.color = rgb(0x3c3c3c);
    v.widgets.hovered.weak_bg_fill = rgb(0xdcdcdc);
    v.widgets.hovered.bg_fill = rgb(0xdcdcdc);
    v.widgets.hovered.bg_stroke.color = rgb(0x696969);
    v.widgets.hovered.fg_stroke.color = rgb(0x000000);
    v.widgets.active.weak_bg_fill = rgb(0xa5a5a5);
    v.widgets.active.bg_fill = rgb(0xa5a5a5);
    v.widgets.active.bg_stroke.color = rgb(0x000000);
    v.widgets.active.fg_stroke.color = rgb(0x000000);
    v.widgets.open.weak_bg_fill = rgb(0xdcdcdc);
    v.widgets.open.bg_fill = rgb(0xdcdcdc);
    v.widgets.open.bg_stroke.color = rgb(0xa0a0a0);
    v.widgets.open.fg_stroke.color = rgb(0x000000);
    v.panel_fill = rgb(0xf8f8f8);
    v.window_fill = rgb(0xf8f8f8);
    v.window_stroke.color = rgb(0xbebebe);
    v.faint_bg_color = rgb(0xf2f2f2);
    v.extreme_bg_color = rgb(0xffffff);
    v.code_bg_color = rgb(0xe6e6e6);
    v.selection.bg_fill = rgb(0x90d1ff);
    v.selection.stroke.color = rgb(0x00537d);
    v.hyperlink_color = rgb(0x009bff);
    v.warn_fg_color = rgb(0xff6400);
    v.error_fg_color = rgb(0xff0000);
    v.text_cursor.stroke.color = rgb(0x00537d);
    v.window_shadow.color = rgba(0x00000019);
    v.popup_shadow.color = rgba(0x00000019);
    v.window_corner_radius = CornerRadius::same(6);
    v.menu_corner_radius = CornerRadius::same(6);
    v.widgets.inactive.corner_radius = CornerRadius::same(2);
    v.widgets.hovered.corner_radius = CornerRadius::same(3);
    v.widgets.inactive.fg_stroke.width = 1.0;
    v.widgets.hovered.fg_stroke.width = 1.5;
    v.widgets.active.fg_stroke.width = 2.0;
    v.window_shadow.blur = 15;
    v.popup_shadow.blur = 8;
    v.weak_text_alpha = 0.6;
}

