/// `egui / Spacing`, applied over `egui::style::Spacing::default()`.
pub fn apply_spacing(s: &mut egui::style::Spacing) {
    s.item_spacing.x = 8.0;
    s.item_spacing.y = 3.0;
    s.window_margin = Margin::same(6);
    s.menu_margin = Margin::same(6);
    s.button_padding.x = 4.0;
    s.button_padding.y = 1.0;
    s.indent = 18.0;
    s.interact_size.x = 40.0;
    s.interact_size.y = 18.0;
    s.slider_width = 100.0;
    s.slider_rail_height = 8.0;
    s.combo_width = 100.0;
    s.text_edit_width = 280.0;
    s.icon_width = 14.0;
    s.icon_width_inner = 8.0;
    s.icon_spacing = 4.0;
    s.tooltip_width = 500.0;
    s.menu_width = 400.0;
    s.menu_spacing = 2.0;
    s.combo_height = 200.0;
    s.scroll.bar_width = 6.0;
    s.scroll.floating_width = 2.0;
}

/// `egui / Text`: the size and family of every text style.
pub fn text_styles() -> BTreeMap<TextStyle, FontId> {
    BTreeMap::from([
        (TextStyle::Small, FontId::new(9.0, FontFamily::Proportional)),
        (TextStyle::Body, FontId::new(12.5, FontFamily::Proportional)),
        (
            TextStyle::Button,
            FontId::new(12.5, FontFamily::Proportional),
        ),
        (
            TextStyle::Monospace,
            FontId::new(12.0, FontFamily::Monospace),
        ),
        (
            TextStyle::Heading,
            FontId::new(18.0, FontFamily::Proportional),
        ),
    ])
}

/// The bundled fonts named by `egui / Text` (`crates/score64-app/assets/fonts`).
pub mod fonts {
    /// `FontFamily::Proportional`'s font name (`egui / Text`).
    pub const PROPORTIONAL_NAME: &str = "Inter";
    /// "Inter" Regular, the `FontFamily::Proportional` font.
    pub const PROPORTIONAL: &[u8] = include_bytes!("../../assets/fonts/Inter-Regular.ttf");
    /// "Inter" Medium, if bundled (`crates/score64-app/assets/fonts/Inter-Medium.ttf`).
    pub const PROPORTIONAL_MEDIUM: Option<&[u8]> =
        Some(include_bytes!("../../assets/fonts/Inter-Medium.ttf"));
    /// `FontFamily::Monospace`'s font name (`egui / Text`).
    pub const MONOSPACE_NAME: &str = "JetBrains Mono";
    /// "JetBrains Mono" Regular, the `FontFamily::Monospace` font.
    pub const MONOSPACE: &[u8] = include_bytes!("../../assets/fonts/JetBrainsMono-Regular.ttf");
}
